/**
 * O-099 `ondra-boot-settle`：把「启动时抢跑」的插件重启一遍。
 *
 * ## 它要解决的问题
 *
 * dsh 的 loader 对一个入口树是**并发 apply** 的，而 `ondra-store-sqlite` 在
 * `apply` 里要先打开数据库、再 `ctx.provide`。那几十毫秒里，所有同步
 * `ctx.get('ondra-store-sqlite')` 的插件都拿到 `undefined`，于是按各自的降级
 * 分支注册成「不可用」——`memory-pool` 没有池表、`memory-graph` 不写边、
 * `snapshot` 不注册、`memory-decay/dedupe/recall` 停在 no-core。日志上看起来
 * 像「存储没装」，实际是**装得晚了一步**。
 *
 * 这一点在本机是可观测的：`ondra-code.log` 里同一次启动中，
 * `ondra.memory-pool 没有可用存储端口` 出现在 `ondra.store-sqlite 存储就绪`
 * **之前**，两行的时间戳是同一秒。
 *
 * ## 为什么不在装配层用 `inject` 修
 *
 * cordis 的 `Inject.resolve` 只把声明归一化成 `{name: null}`，等待机制挂在
 * 「服务注册时的 `notify`」上，对**尚未 provide 的服务**不阻塞——实测：
 * `ondra-memory-pool` 声明了 `inject: [ondra-store-sqlite]`，仍然在 store
 * 之前 apply。而插件自己「刻意不声明 inject」也是对的：声明后上游缺席会整
 * 插件 PENDING，那是更难查的失败形态。
 *
 * ## 它怎么做
 *
 * 用 `ctx.inject([...服务], cb)`：**服务都就绪时才执行回调**（cordis 的
 * 回调式注入，与 fiber 级 inject 是两套机制）。回调里按入口 id 找到那些降级
 * 插件的 fiber，`await fiber.restart()`——dispose 再 reload，此时依赖都在，
 * 插件第二轮 apply 就能拿到真依赖。
 *
 * 机制已用最小场景单独验证（`tool/boot_settle_probe.mjs`）：慢存储 50ms 后
 * 才 provide，消费者先 apply 得到 `available: false`，重启后变成 `true`。
 *
 * ## 它**不**做什么
 *
 * - 不重启「依赖本来就不存在」的插件（`asr` 没有 privacy、`installer` 没有
 *   manifest、`persona-loader` 没有随包人设）。那些重启一万次也一样，
 *   名单由装配层显式给，不由本插件猜。
 * - 不修改任何插件源码。上游包保持原样，时序问题在这里补。
 * - 失败不抛出：任何一个目标重启失败都只记一条 warn，宿主的启动不能被它拖住。
 *
 * ## 为什么没有构建步骤
 *
 * 全插件一百多行，只做一件事。为它建一套 TS 工程 + 依赖 cordis 类型，换来的
 * 是一个在拷贝目录里解析不到的 `extends` 链——比代码本身更容易坏。
 * 入口就是 `lib/index.js`，`package.json` 的 `main` 直接指向它。
 */

/** 默认不重启任何插件：没有显式名单时本插件什么都不做。 */
const DEFAULTS = {
  services: [],
  targets: [],
  graceMs: 500,
}

/**
 * 判断一条 fiber 是不是装配层里那个入口。
 *
 * 入口 id 在树里会被前面的分组带上命名空间：`- id: ondra-memory-pool`
 * 挂到 include 分组下之后变成 `include:ondra-memory-pool`。所以比较的是
 * **最后一段**，而不是整串；同时留一条按 fiber 名字比的后路——分组层级
 * 将来若再变一层，名字仍然是对的。
 *
 * @param fiber 注册表里的一条 fiber。
 * @param id 装配层里写的入口 id。
 * @returns 命中返回 true。
 */
function matches(fiber, id) {
  const entryId = fiber.entry?.id
  if (typeof entryId === 'string' && entryId.length > 0) {
    const bare = entryId.slice(entryId.lastIndexOf(':') + 1)
    if (bare === id) return true
  }
  return fiber.name === id
}

/**
 * 在注册表里按入口 id 找插件的第一条 fiber。
 *
 * 不能按 `runtime.name` 找：cordis 取的是插件模块的 `name`，而所有插件的入口
 * 都叫 `apply`，于是 `runtime.name` 多半是 `undefined`。入口 id 才是装配层
 * 认得的那个名字（`- id: ondra-memory-pool`），也是用户能在 YAML 里改的那个。
 *
 * @param ctx 宿主上下文。
 * @param id 装配层里写的入口 id。
 * @returns 找到的 fiber，或 `undefined`。
 */
function findFiber(ctx, id) {
  for (const runtime of ctx.registry.values()) {
    for (const fiber of runtime.fibers) {
      if (matches(fiber, id)) return fiber
    }
  }
  return undefined
}

/**
 * Cordis 入口。
 *
 * @param ctx 宿主上下文。
 * @param config 装配层给的名单：等哪些服务、重启哪些插件、等多久。
 */
export function apply(ctx, config) {
  const raw = config && typeof config === 'object' ? config : {}
  const services = Array.isArray(raw.services) ? raw.services : DEFAULTS.services
  const targets = Array.isArray(raw.targets) ? raw.targets : DEFAULTS.targets
  const graceMs =
    typeof raw.graceMs === 'number' && Number.isFinite(raw.graceMs)
      ? Math.max(0, raw.graceMs)
      : DEFAULTS.graceMs

  const identity = ctx.get('ondra-identity')
  const log = ctx.logger(identity ? identity.loggerName('boot-settle') : 'ondra.boot-settle')

  // 没有名单就等于没装：不在日志里留噪音，也不注册任何服务。
  if (services.length === 0 || targets.length === 0) return

  if (typeof ctx.inject !== 'function') {
    log.warn('宿主没有 ctx.inject：无法等依赖就绪，本插件不做事')
    return
  }

  // 一条装载日志：区分「没被加载」与「加载了但回调没触发」。这两件事在排查时
  // 完全不同，而本插件修的正是这类静默失灵。
  log.info(
    '装载：等 %s 就绪后重启 %d 个抢跑插件（宽限 %dms）',
    services.join(' + '),
    targets.length,
    graceMs,
  )

  ctx.inject(services, async () => {
    try {
      // 让首轮 apply 走完再动手：restart 一个正在 apply 的 fiber 会把它的
      // 卸载与重载撞在一起。
      if (graceMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, graceMs))
      }

      const done = []
      const missing = []
      const failed = []
      for (const id of targets) {
        const fiber = findFiber(ctx, id)
        if (!fiber) {
          missing.push(id)
          continue
        }
        try {
          await fiber.restart()
          done.push(id)
        } catch (error) {
          failed.push(`${id}: ${error instanceof Error ? error.message : String(error)}`)
        }
      }

      // 诊断：重启之后，同一个 scope 里还能不能看见早期的服务。若这里变成
      // 「不可见」，说明 restart 换了作用域，重启法对软依赖插件不成立——
      // 那要换别的修法，不能装作已经修好。
      const layout = ctx.get('ondra-path-layout')
      const store = ctx.get('ondra-store-sqlite')
      log.info(
        '重启后作用域自检：path-layout %s，store-sqlite %s',
        layout === undefined ? '不可见' : '可见',
        store === undefined ? '不可见' : '可见',
      )

      // 一条 INFO 说清结果：这是启动日志里唯一能证明「时序已经补上」的地方。
      log.info(
        '依赖就绪后重启 %d 个抢跑插件（等 %dms）；找不到 %d 个，失败 %d 个',
        done.length,
        graceMs,
        missing.length,
        failed.length,
      )
      if (missing.length > 0) log.info('不在本 profile 里（可能被关掉了）：%s', missing.join('、'))
      for (const line of failed) log.warn('重启失败 %s', line)
    } catch (error) {
      // 兜底：本插件的职责是补救，不该成为新的启动失败源。
      log.warn('重启流程异常：%s', error instanceof Error ? error.message : String(error))
    }
  })
}
